{
  "name": "opencode-kimi-full",
  "version": "1.4.0",
  "description": "OpenCode plugin that brings the official Kimi OAuth device flow and Kimi-specific coding request fields to opencode, matching upstream kimi-cli.",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/lemon07r/opencode-kimi-full.git"
  },
  "homepage": "https://github.com/lemon07r/opencode-kimi-full#readme",
  "bugs": {
    "url": "https://github.com/lemon07r/opencode-kimi-full/issues"
  },
  "publishConfig": {
    "access": "public",
    "provenance": true
  },
  "type": "module",
  "main": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts",
    "./server": "./src/index.ts",
    "./tui": "./src/tui.tsx"
  },
  "files": [
    "src",
    "README.md",
    "AGENTS.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "kimi",
    "kimi-for-coding",
    "moonshot",
    "oauth",
    "device-flow",
    "reasoning-effort",
    "prompt-cache-key"
  ],
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.4.6"
  },
  "engines": {
    "opencode": ">=1.4.6"
  },
  "dependencies": {
    "@opentui/core": "0.1.99",
    "@opentui/solid": "0.1.99"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.4.7",
    "@types/node": "^22.0.0",
    "typescript": "^5.6.0"
  }
}
